import unittest


def namespace_report(cls, *instances):
    class_attrs = sorted(
        name for name in vars(cls)
        if not (name.startswith("__") and name.endswith("__"))
    )
    return {
        "class": cls.__name__,
        "classAttrs": class_attrs,
        "instanceAttrs": [sorted(vars(instance)) for instance in instances],
    }


class Point:
    kind = "2d"

    def __init__(self, x, y):
        self.x = x
        self.y = y


class NamespaceReportTest(unittest.TestCase):
    def test_class_name(self):
        self.assertEqual(namespace_report(Point)["class"], "Point")

    def test_own_class_attrs(self):
        self.assertEqual(namespace_report(Point)["classAttrs"], ["kind"])

    def test_instance_attrs(self):
        self.assertEqual(
            namespace_report(Point, Point(1, 2), Point(3, 4))["instanceAttrs"],
            [["x", "y"], ["x", "y"]],
        )

    def test_instance_attr_is_not_class_attr(self):
        report = namespace_report(Point, Point(1, 2))
        self.assertNotIn("x", report["classAttrs"])

    def test_no_instances(self):
        self.assertEqual(namespace_report(Point)["instanceAttrs"], [])


if __name__ == "__main__":
    unittest.main()

