from functools import partial


class Greeter:
    def hello(self, name):
        return "hello," + name


def bind(func, instance):
    return partial(func, instance)


def is_bound_to(method, instance):
    return getattr(method, "__self__", None) is instance


class BindingTest(unittest.TestCase):
    def test_bind_passes_instance_as_self(self):
        greeter = Greeter()
        self.assertEqual(bind(Greeter.hello, greeter)("amy"), "hello,amy")

    def test_bind_matches_bound_method(self):
        greeter = Greeter()
        self.assertEqual(bind(Greeter.hello, greeter)("amy"), greeter.hello("amy"))

    def test_reusable(self):
        greeter = Greeter()
        hello = bind(Greeter.hello, greeter)
        self.assertEqual([hello("a"), hello("b")], ["hello,a", "hello,b"])

    def test_is_bound_to(self):
        greeter = Greeter()
        self.assertTrue(is_bound_to(greeter.hello, greeter))
        self.assertFalse(is_bound_to(Greeter.hello, greeter))


