        self.assertIsInstance(Duration.from_minutes(1), Duration)
        half = Half.from_hours(1)
        self.assertIsInstance(half, Half)
        self.assertEqual(half.seconds, 1800)

    def test_staticmethod_valid_seconds(self):
        self.assertTrue(Duration.is_valid_seconds(0))
        self.assertFalse(Duration.is_valid_seconds(True))
        self.assertFalse(Duration.is_valid_seconds(-1))
