import unittest


class ListLogger:
    def __init__(self):
        self.entries = []

    def log(self, message):
        self.entries.append(message)
        return "log:" + message


class Service:
    def __init__(self, logger):
        self.logger = logger

    def log(self, message):
        return self.logger.log(message)

    def process(self, items):
        count = 0
        for item in items:
            self.logger.log("item:" + str(item))
            count += 1
        return count


class CompositionTest(unittest.TestCase):
    def test_delegates_to_logger(self):
        logger = ListLogger()
        self.assertEqual(Service(logger).log("hello"), "log:hello")
        self.assertEqual(logger.entries, ["hello"])

    def test_process_counts_and_logs(self):
        logger = ListLogger()
        self.assertEqual(Service(logger).process(["a", "b"]), 2)
        self.assertEqual(logger.entries, ["item:a", "item:b"])

    def test_service_does_not_inherit_logger(self):
        self.assertEqual([base.__name__ for base in Service.__mro__], ["Service", "object"])

    def test_accepts_any_logger(self):
        class CollectingLogger:
            def __init__(self):
                self.seen = []

            def log(self, message):
                self.seen.append(message.upper())
                return "ok"

        logger = CollectingLogger()
        self.assertEqual(Service(logger).log("hi"), "ok")
        self.assertEqual(logger.seen, ["HI"])


