@dataclass(frozen=True)
class Success:
    value: int

    @property
    def is_ok(self):
        return True


@dataclass(frozen=True)
class Failure:
    message: str

    @property
    def is_ok(self):
        return False


Result = Union[Success, Failure]


def divide(a: int, b: int) -> Result:
